    }
    off(type, handler) {
        if (this.all[type]) {
            const indexOf = this.all[type].indexOf(handler);
            if (indexOf) {
                this.all[type].splice(indexOf, 1);
            }
        }
    }
    emit(type, evt) {
        (this.all[type] || []).map((handler) => { handler(evt); });
    }
    reset() {
        this.all = {};
    }
}

